_templateId = "accountHubEmailPasswordFormTemplate";
/**
 * The selector to get the form element.
 *
 * @type {string}
 * @protected
 */
_formSelector = "#passwordForm";
/**
 * The selector to get the password input.
 *
 * @type {string}
 * @protected
 */
_passwordSelector = "#password";
/**
 * The selector to get the remember password checkbox.
 *
 * @type {string}
 * @protected
 */
_rememberPasswordSelector = "#rememberPassword";

/**
 * The remember checkbox.
 *
 * @type {HTMLInputElement}
 */
#rememberPassword;

connectedCallback() {
  if (this.hasConnected) {
    return;
  }
  this.hasConnected = true;

  super.connectedCallback();

  const template = document
    .getElementById(this._templateId)
    .content.cloneNode(true);
  this.appendChild(template);

  this.#password = this.querySelector(this._passwordSelector);
  this.#rememberPassword = this.querySelector(this._rememberPasswordSelector);

  this.#password.focus();

  // Disable the remember password checkbox if the pref is false.
  this.#setRememberPasswordInput(this.rememberSignons);

  this.#password.addEventListener("input", this);
}

handleEvent(event) {
  switch (event.type) {
    case "input":
      this.dispatchEvent(
        new CustomEvent("config-updated", {
          bubbles: true,
          detail: { completed: this.#password.checkValidity() },
        })
      );
      break;
    default:
      break;
  }
}

/**
 * Resets the password field.
 */
setState() {
  this.querySelector(this._formSelector).reset();
  this.#password.focus();
}

/**
 * Return the current state of the email setup form.
 *
 * @returns {UsernamePassword}
 */
captureState() {
  return {
    password: this.#password.value,
    rememberPassword: this.#rememberPassword.checked,
  };
}
